<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();$id=(int)$u['id'];$q=db()->prepare("SELECT DISTINCT x.id,x.name FROM users x JOIN study_requests r ON r.status='accepted' AND ((r.sender_id=? AND r.receiver_id=x.id) OR (r.receiver_id=? AND r.sender_id=x.id)) ORDER BY x.name");$q->execute([$id,$id]);$contacts=$q->fetchAll();$other=(int)($_GET['user']??($contacts[0]['id']??0));$allowed=false;foreach($contacts as $c)if((int)$c['id']===$other)$allowed=true;if($other&&!$allowed)$other=0;$person=null;$msgs=[];if($other){$q=db()->prepare('SELECT id,name FROM users WHERE id=?');$q->execute([$other]);$person=$q->fetch();$q=db()->prepare('SELECT * FROM messages WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?) ORDER BY created_at');$q->execute([$id,$other,$other,$id]);$msgs=$q->fetchAll();db()->prepare('UPDATE messages SET is_read=1 WHERE sender_id=? AND receiver_id=?')->execute([$other,$id]);}page_start('Messages'); ?><div class="card"><div class="row g-0"><div class="col-md-4 col-lg-3 border-end"><div class="p-3 fw-bold">Conversations</div><?php foreach($contacts as $c): ?><a class="d-flex align-items-center gap-2 p-3 border-top text-decoration-none <?= (int)$c['id']===$other?'bg-light':'' ?>" href="?user=<?= (int)$c['id'] ?>"><div class="avatar avatar-sm"><?= e(mb_substr($c['name'],0,1)) ?></div><span><?= e($c['name']) ?></span></a><?php endforeach ?><?php if(!$contacts): ?><div class="empty">Accept a partner request to start a conversation.</div><?php endif ?></div><div class="col-md-8 col-lg-9"><?php if($person): ?><div class="p-3 border-bottom fw-bold"><?= e($person['name']) ?></div><div class="chat-box" id="chatbox"><?php foreach($msgs as $m): ?><div class="bubble <?= (int)$m['sender_id']===$id?'mine':'' ?>"><div><?= nl2br(e($m['message'])) ?></div><small class="text-secondary"><?= e($m['created_at']) ?></small></div><?php endforeach ?><?php if(!$msgs): ?><div class="empty">Say hello and start planning a study session.</div><?php endif ?></div><form class="d-flex gap-2 p-3 border-top" method="post" action="../actions/message.php"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="receiver_id" value="<?= $other ?>"><input class="form-control" name="message" maxlength="2000" placeholder="Write a message..." required><button class="btn btn-primary">Send</button></form><?php else: ?><div class="empty">Choose an accepted partner to view your conversation.</div><?php endif ?></div></div></div><?php page_end(); ?>
